// maybeTerm returns the term of the entry at index i, if there
// is any.
func (u *unstable) maybeTerm(i uint64) (uint64, bool) {
	if i < u.offset {
		if u.snapshot != nil && u.snapshot.GetMetadata().GetIndex() == i {
			return u.snapshot.GetMetadata().GetTerm(), true
