 }}}
 s.t.Fatal("no leader after recovery")
}

func TestAsyncDuplicateVoteDurabilityRegression(t *testing.T) {
 s:=newSafetySim(t,true,false,false)
 s.campaign(1);s.collect(1);s.thread(1,true);for s.respond(1){};s.collect(1)
 vote:=s.take(1,2,pb.MsgVote);require.NotNil(t,vote)
 s.deliver(vote);s.collect(2) // the vote write is now queued, not durable
 s.deliver(vote);s.collect(2) // duplicate must wait behind that write
 if escaped:=s.take(2,1,pb.MsgVoteResp);escaped!=nil {s.deliver(escaped);s.collect(1)}
 s.crash(2);s.net=nil
 s.campaign(3);s.collect(3);s.thread(3,true);for s.respond(3){};s.collect(3)
 v:=s.take(3,2,pb.MsgVote);require.NotNil(t,v);s.deliver(v);s.collect(2);s.thread(2,true)
 v=s.take(2,3,pb.MsgVoteResp);require.NotNil(t,v);s.deliver(v)
 s.progress()
}

func TestAsyncDuplicateAppendDurabilityRegression(t *testing.T) {
 s:=newSafetySim(t,true,false,false);s.elect(1)
 require.NoError(t,s.nodes[1].rn.Propose([]byte("lost")));s.collect(1)
 app:=s.take(1,2,pb.MsgApp);require.NotNil(t,app)
 s.deliver(app);s.collect(2);s.deliver(app);s.collect(2)
 // Node 1's local append is also not durable. Only an escaped duplicate
 // acknowledgement can let it commit and node 2 apply this proposal.
 s.thread(1,true);for s.respond(1){};s.collect(1)
 if ack:=s.take(2,1,pb.MsgAppResp);ack!=nil {
  s.deliver(ack);s.collect(1)
  for s.thread(1,true){};for s.respond(1){};s.collect(1);for s.thread(1,false){};for s.respond(1){}
 }
 // Directly test the underlying durable promise as well as cluster recovery.
 require.Nil(t,s.take(2,1,pb.MsgAppResp),"append response bypassed queued persistence")
 require.Equal(t,uint64(2),s.nodes[1].applied,"committed using an unpersisted follower acknowledgement")
 s.crash(2);s.progress()
}

func TestDelayedAppendCannotConfirmReadRegression(t *testing.T) {
 for _,async:=range []bool{false,true} {t.Run(fmt.Sprint(async),func(t *testing.T){
  s:=newSafetySim(t,async,false,false);s.elect(1)
  // Capture a genuine response before the read exists.
  s.nodes[1].rn.Tick();s.collect(1)
  hb:=s.take(1,2,pb.MsgHeartbeat);require.NotNil(t,hb);s.deliver(hb);s.collect(2)
  // A proposal provides an append response from the old leader's term.
  require.NoError(t,s.nodes[1].rn.Propose([]byte("old")));s.collect(1)
  app:=s.take(1,2,pb.MsgApp);require.NotNil(t,app);s.deliver(app);s.collect(2)
  if async {s.thread(2,true)}
  ack:=s.take(2,1,pb.MsgAppResp);require.NotNil(t,ack)
  // Isolate 1. The remaining majority elects 3 and applies newer entries.
  s.net=nil;s.campaign(3)
  for k:=0;k<1000;k++ {
   work:=false
   for _,id:=range []uint64{2,3}{if s.collect(id){work=true};if s.thread(id,true){work=true};if s.thread(id,false){work=true};if s.respond(id){work=true}}
   if len(s.net)>0 {m:=s.net[0];s.net=s.net[1:];if m.GetFrom()!=1 && m.GetTo()!=1 {s.deliver(m)};work=true};if !work{break}
  }
  require.Equal(t,StateLeader,s.nodes[3].rn.BasicStatus().RaftState)
  require.Greater(t,s.nodes[3].applied,s.nodes[1].applied)
  s.read(1,"after-new-leader");s.deliver(ack);s.collect(1)
  s.progress()
 })}
}

